using System.Linq;using UnityEngine;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class InspectHud06APlay{public static string Main(){var v=Object.FindFirstObjectByType<RailwayOverview>();var r=v.Railway.SelectedRoute;return new JObject{{"train",JsonUtility.ToJson(r.train)},{"pending",JsonUtility.ToJson(r.pending)},{"buttons",new JArray(v.Root.GetComponentsInChildren<UnityEngine.UI.Button>(true).Select(b=>{var t=b.GetComponentInChildren<TMPro.TMP_Text>(true);return new JObject{{"name",b.name},{"text",t.text},{"rect",t.rectTransform.rect.ToString()},{"font",t.fontSize},{"color",t.color.ToString()},{"active",b.gameObject.activeInHierarchy}};}))}}.ToString();}}
